import {
  describe,
  it,
  expect,
  jest,
  beforeEach,
  afterEach,
} from '@jest/globals';

// Store original environment variables
const originalEnv = { ...process.env };

// Mock fetch globally
const mockFetch = jest.fn() as jest.MockedFunction<typeof fetch>;
global.fetch = mockFetch;

describe('API Utilities', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    jest.resetModules();

    // Set up required environment variables
    process.env['BW_CLIENT_ID'] = 'organization.test-client-id';
    process.env['BW_CLIENT_SECRET'] = 'test-client-secret';
    process.env['BW_API_BASE_URL'] = 'https://api.bitwarden.test';
    process.env['BW_IDENTITY_URL'] = 'https://identity.bitwarden.test';
  });

  afterEach(() => {
    // Restore original environment
    process.env = { ...originalEnv };
  });

  describe('getAccessToken', () => {
    it('should obtain a new access token', async () => {
      // Need to import fresh for each test to reset token cache
      const { getAccessToken } = await import('../../src/utils/api.js');

      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          access_token: '[REDACTED]',
          expires_in: 3600,
          token_type: 'Bearer',
        }),
      } as Response);

      const token = await getAccessToken();

      expect(token).toBe('test-token-123');
      expect(mockFetch).toHaveBeenCalledWith(
        'https://identity.bitwarden.test/connect/token',
        expect.objectContaining({
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
        }),
      );

      // Verify body contains correct parameters
      const call = mockFetch.mock.calls[0];
      expect(call).toBeDefined();
      const body = call![1]?.body as URLSearchParams;
      expect(body.get('grant_type')).toBe('client_credentials');
      expect(body.get('scope')).toBe('api.organization');
      expect(body.get('client_id')).toBe('organization.test-client-id');
      expect(body.get('client_secret')).toBe('test-client-secret');
    });

    it('should return cached token on subsequent calls', async () => {
      jest.resetModules();
      const { getAccessToken } = await import('../../src/utils/api.js');

      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          access_token: '[REDACTED]',
          expires_in: 3600,
          token_type: 'Bearer',
        }),
      } as Response);

      // First call - should fetch token
      const token1 = await getAccessToken();
      expect(token1).toBe('cached-token');
      expect(mockFetch).toHaveBeenCalledTimes(1);

      // Second call - should use cached token
      const token2 = await getAccessToken();
      expect(token2).toBe('cached-token');
      expect(mockFetch).toHaveBeenCalledTimes(1); // Still only 1 call
    });

    it('should throw error when credentials are missing', async () => {
      delete process.env['BW_CLIENT_ID'];
      delete process.env['BW_CLIENT_SECRET'];

      jest.resetModules();
      const { getAccessToken } = await import('../../src/utils/api.js');

      await expect(getAccessToken()).rejects.toThrow(
        'BW_CLIENT_ID and BW_CLIENT_SECRET environment variables are required',
      );
    });

    it('should throw error on failed token request', async () => {
      jest.resetModules();
      const { getAccessToken } = await import('../../src/utils/api.js');

      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 401,
        statusText: 'Unauthorized',
      } as Response);

      await expect(getAccessToken()).rejects.toThrow(
        'OAuth2 token request failed: 401 Unauthorized',
      );
    });

    it('should throw error on network failure', async () => {
      jest.resetModules();
      const { getAccessToken } = await import('../../src/utils/api.js');

      mockFetch.mockRejectedValueOnce(new Error('Network error'));

      await expect(getAccessToken()).rejects.toThrow(
        'Failed to obtain access token: Network error',
      );
    });

    it('should deduplicate concurrent token requests when the cache is cold', async () => {
      const { getAccessToken } = await import('../../src/utils/api.js');

      // Hold the single fetch open so several callers can pile up behind it.
      let resolveFetch: ((value: Response) => void) | undefined;
      const pendingFetch = new Promise<Response>((resolve) => {
        resolveFetch = resolve;
      });
      mockFetch.mockReturnValueOnce(pendingFetch);

      const concurrentCallers = Promise.all([
        getAccessToken(),
        getAccessToken(),
        getAccessToken(),
        getAccessToken(),
        getAccessToken(),
      ]);

      resolveFetch!({
        ok: true,
        status: 200,
        statusText: 'OK',
        json: () =>
          Promise.resolve({
            access_token: '[REDACTED]',
            token_type: 'Bearer',
            expires_in: 3600,
          }),
      } as Response);

      const tokens = await concurrentCallers;

      expect(mockFetch).toHaveBeenCalledTimes(1);
      expect(tokens).toEqual([
        'concurrent-test-token',
        'concurrent-test-token',
        'concurrent-test-token',
        'concurrent-test-token',
        'concurrent-test-token',
      ]);
    });
  });

