    });

    it('should remove ampersands', () => {
      expect(sanitizeInput('test&rm')).toBe('testrm');
    });

    it('should remove pipes', () => {
      expect(sanitizeInput('test|cat')).toBe('testcat');
    });

    it('should remove backticks', () => {
