    it('should handle boolean flags', () => {
      const result = buildSafeCommand('delete', [
        'item',
        'id123',
        '--permanent',
      ]);
      expect(result).toEqual(['delete', 'item', 'id123', '--permanent']);
    });
  });
});

describe('CLI Command Security Integration', () => {
  it('should sanitize dangerous characters from base command', () => {
    // Dangerous characters are removed from base command
    const result = buildSafeCommand('list; rm -rf /', []);
    // Semicolon removed, spaces collapsed, result trimmed
    expect(result[0]).toBe('list rm -rf /');
    // Note: isValidBitwardenCommand checks first word after splitting on spaces,
    // so 'list rm -rf /' still has 'list' as valid first word.
    // The security comes from executeCliCommand which validates BEFORE execution.
  });

  it('should reject completely invalid commands', () => {
    const sanitized = sanitizeInput('rm;echo');
    // 'rmecho' is not a valid Bitwarden command
    expect(isValidBitwardenCommand(sanitized)).toBe(false);
  });

  it('should allow special characters in parameters (spawn handles them safely)', () => {
    // Parameters with shell metacharacters are safe because:
    // 1. spawn() is called with shell: false
    // 2. Arguments are passed as array elements, not string interpolation
    const result = buildSafeCommand('get', ['item', '$(whoami)']);
    expect(result).toEqual(['get', 'item', '$(whoami)']);
    // The command is valid, and $(whoami) is just a literal string
    expect(isValidBitwardenCommand('get')).toBe(true);
  });

  it('should block null byte injection in parameters', () => {
    // Null bytes could be used to truncate strings in some contexts
    expect(() => {
      buildSafeCommand('get', ['item\0', 'malicious']);
    }).toThrow('Invalid parameter detected');
  });

  it('should block newline injection in parameters', () => {
    // Newlines could be used for log injection or argument manipulation
    expect(() => {
      buildSafeCommand('list', ['items\n--dangerous-flag']);
    }).toThrow('Invalid parameter detected');
  });

  it('should require valid Bitwarden command after sanitization', () => {
    // Test the full validation pipeline
    const sanitized = sanitizeInput('exec');
    const isValid = isValidBitwardenCommand(sanitized);
    expect(isValid).toBe(false);
  });
});

import { afterEach, beforeEach, describe, expect, it } from '@jest/globals';
import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  _resetBwInvocationCacheForTests,
  resolveBwInvocation,
} from '../../src/utils/bw-cli.js';

const originalPlatform = process.platform;
const originalEnv = { ...process.env };

function setPlatform(platform: NodeJS.Platform): void {
  Object.defineProperty(process, 'platform', { value: platform });
}

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'bw-cli-test-'));
}

describe('resolveBwInvocation', () => {
  let tmpDirs: string[] = [];

  beforeEach(() => {
    _resetBwInvocationCacheForTests();
    tmpDirs = [];
    delete process.env['BW_CLI_PATH'];
  });

  afterEach(() => {
    Object.defineProperty(process, 'platform', { value: originalPlatform });
    process.env = { ...originalEnv };
    for (const dir of tmpDirs) {
      fs.rmSync(dir, { recursive: true, force: true });
    }
    _resetBwInvocationCacheForTests();
  });

  function tempDir(): string {
    const dir = makeTempDir();
    tmpDirs.push(dir);
    return dir;
  }

  it('returns a bare `bw` on POSIX with no override (PATH/execvp handles it)', () => {
    setPlatform('linux');
    expect(resolveBwInvocation()).toEqual({ command: 'bw', prefixArgs: [] });
  });

  it('runs a JS entry point via the current Node runtime when BW_CLI_PATH is a .js file', () => {
    setPlatform('linux');
    const dir = tempDir();
    const jsEntry = path.join(dir, 'bw.js');
    fs.writeFileSync(jsEntry, '// fake cli');
    process.env['BW_CLI_PATH'] = jsEntry;

    expect(resolveBwInvocation()).toEqual({
      command: process.execPath,
      prefixArgs: [jsEntry],
    });
  });

  it('spawns a real executable directly when BW_CLI_PATH points at a binary', () => {
    setPlatform('linux');
    const dir = tempDir();
    const binary = path.join(dir, 'bw');
    fs.writeFileSync(binary, '#!/bin/sh\n');
    process.env['BW_CLI_PATH'] = binary;

    expect(resolveBwInvocation()).toEqual({
      command: binary,
      prefixArgs: [],
    });
  });

  it('Windows: resolves the npm .cmd shim to its JS entry run via Node', () => {
    setPlatform('win32');
    const prefix = tempDir();

    // Simulate the npm global layout: shim at <prefix>, package under
    // <prefix>/node_modules/@bitwarden/cli.
    fs.writeFileSync(path.join(prefix, 'bw.cmd'), '@echo off\n');
    const pkgDir = path.join(prefix, 'node_modules', '@bitwarden', 'cli');
    fs.mkdirSync(pkgDir, { recursive: true });
    fs.writeFileSync(
      path.join(pkgDir, 'package.json'),
      JSON.stringify({ bin: { bw: 'build/bw.js' } }),
    );
    const jsEntry = path.join(pkgDir, 'build', 'bw.js');
    fs.mkdirSync(path.dirname(jsEntry), { recursive: true });
    fs.writeFileSync(jsEntry, '// fake cli');

    process.env['PATH'] = prefix;
    // Lowercase to match the fixture filenames so the test is
    // deterministic on case-sensitive (Linux CI) and case-insensitive
    // (macOS) filesystems alike. Real Windows is case-insensitive.
    process.env['PATHEXT'] = '.com;.exe;.bat;.cmd';

    expect(resolveBwInvocation()).toEqual({
      command: process.execPath,
      prefixArgs: [jsEntry],
    });
  });

  it('Windows: prefers a real bw.exe over the .cmd shim', () => {
    setPlatform('win32');
    const prefix = tempDir();
    const exe = path.join(prefix, 'bw.exe');
    fs.writeFileSync(exe, 'MZ');
    fs.writeFileSync(path.join(prefix, 'bw.cmd'), '@echo off\n');

    process.env['PATH'] = prefix;
    // Lowercase to match the fixture filenames so the test is
    // deterministic on case-sensitive (Linux CI) and case-insensitive
    // (macOS) filesystems alike. Real Windows is case-insensitive.
    process.env['PATHEXT'] = '.com;.exe;.bat;.cmd';

    expect(resolveBwInvocation()).toEqual({ command: exe, prefixArgs: [] });
  });

  it('Windows: falls back to bare `bw` when nothing is found on PATH', () => {
    setPlatform('win32');
    process.env['PATH'] = tempDir(); // empty dir
    // Lowercase to match the fixture filenames so the test is
    // deterministic on case-sensitive (Linux CI) and case-insensitive
    // (macOS) filesystems alike. Real Windows is case-insensitive.
    process.env['PATHEXT'] = '.com;.exe;.bat;.cmd';

    expect(resolveBwInvocation()).toEqual({ command: 'bw', prefixArgs: [] });
  });

  it('memoizes the result across calls', () => {
    setPlatform('linux');
    const first = resolveBwInvocation();
    const second = resolveBwInvocation();
    expect(second).toBe(first);
  });
});
